INSERT INTO public.products (name, price, image_url, affiliate_url, asin, audience_tags, occasion_tags, price_range, description, review_quote) VALUES
  -- === GIFTS FOR MEN (BBQ/Cooking/Grooming) ===
  ('Clean Skin Club Clean Towels XL 50ct', 17.95, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07PBXXNCY?tag=GIFTHIVE-20', 'B07PBXXNCY', ARRAY['for-her']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Disposable ultrasonic facial towels for a hygienic cleanse every single time.', 'My skin finally stopped breaking out after I switched to these clean towels.'),
  ('Alpha Grillers Meat Thermometer Digital', 14.97, 'https://images.unsplash.com/photo-1587829741381-af9386f64498?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B00S93EQUK?tag=GIFTHIVE-20', 'B00S93EQUK', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Instant-read digital thermometer that takes the guesswork out of grilling.', 'Steak comes out perfect every time now, no more second-guessing the temp.'),
  ('Whiskey Smoker Kit with Torch', 47.99, 'https://images.unsplash.com/photo-1587829741381-af9386f64498?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0BJV68C17?tag=GIFTHIVE-20', 'B0BJV68C17', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Old-fashioned cocktail smoker kit with butane torch and wood chips for the home bartender.', 'Made me feel like a real mixologist at my own kitchen counter.'),
  ('Rolling Grill Basket Stainless Steel', 23.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CGX3ZGBK?tag=GIFTHIVE-20', 'B0CGX3ZGBK', ARRAY['for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Durable rotisserie-style basket that flips veggies and shrimp without losing them to the coals.', 'No more chasing onions through the grates, this basket changed my BBQ game.'),
  ('Astercook Bamboo Cutting Boards Set', 24.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0FH6YL3XC?tag=GIFTHIVE-20', 'B0FH6YL3XC', ARRAY['for-him','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Three-piece bamboo boards in graduated sizes, gentle on knives and easy on the eyes.', 'They look gorgeous on the counter and my chef knife stays sharper longer.'),
  ('Kaluns Grilling Accessories Set', 29.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B079J4KT8H?tag=GIFTHIVE-20', 'B079J4KT8H', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Complete stainless steel BBQ tool set with everything he needs to man the grill.', 'Holds up to high heat and the handles feel solid, not flimsy like cheaper sets.'),
  ('Fathers Day Nuts Gift Basket', 32.95, 'https://images.unsplash.com/photo-1466637574449-8f0937778c1f?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B08X94JGJ1?tag=GIFTHIVE-20', 'B08X94JGJ1', ARRAY['for-him','for-parents']::text[], ARRAY['christmas','thanks']::text[], 'mid', 'Assorted roasted nuts and sweets in a reusable wooden crate, ready to gift.', 'Dad kept the box long after the snacks were gone, that says it all.'),
  ('Pop-the-Top Beer Bottle Opener', 9.99, 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B015MSDYKM?tag=GIFTHIVE-20', 'B015MSDYKM', ARRAY['for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Wall-mounted bottle opener that catches the cap so the floor stays clean.', 'Satisfying pop every time and I stopped finding caps in the couch cushions.'),
  ('Rak Magnetic Wristband Tool', 17.99, 'https://images.unsplash.com/photo-1587829741381-af9386f64498?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B01HRCU3SW?tag=GIFTHIVE-20', 'B01HRCU3SW', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Strong magnetic wristband holds screws and nails while both hands stay free to work.', 'I built a whole bookshelf without dropping a single screw, total game changer.'),
  ('Fairwin Ratchet Web Belt', 14.99, 'https://images.unsplash.com/photo-1620799140408-edc6dcb6d633?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07PGV4ZRD?tag=GIFTHIVE-20', 'B07PGV4ZRD', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Slide-fit ratcheting belt with no holes, just micro-adjustments for the perfect fit.', 'Finally a belt that fits after a big meal without wrestling a buckle.'),
  ('HAPPY NUTS Comfort Cream Deodorant', 14.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07S1BNNYD?tag=GIFTHIVE-20', 'B07S1BNNYD', ARRAY['for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Aluminum-free deodorant cream with a smooth glide and all-day odor protection.', 'Goes on like lotion and I stopped smelling myself by lunchtime, finally.'),
  ('Aceoce Manicure Set Travel Case', 9.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07GGR1N4Y?tag=GIFTHIVE-20', 'B07GGR1N4Y', ARRAY['for-him','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Compact leather case with twelve stainless steel grooming tools for nails and brows.', 'Sharper than I expected and the case actually snaps shut instead of falling open.'),
  ('Viking Revolution Beard Comb & Brush', 9.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B06X3ZL2CV?tag=GIFTHIVE-20', 'B06X3ZL2CV', ARRAY['for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Boar bristle brush and double-sided comb to tame beard itch and distribute oils.', 'The brush softened my beard in a week, my partner actually noticed.'),
  ('Yougai Nail Clippers Set 18 Pcs', 9.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B078YQW3RN?tag=GIFTHIVE-20', 'B078YQW3RN', ARRAY['for-him','for-her']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Full grooming kit with clippers, files, and tools tucked into a slim faux-leather case.', 'Has every tool I needed and the clippers cut cleanly with no jagged edges.'),
  ('Yeipis Back Scratcher 3 Pack', 5.99, 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0BHCPFPM8?tag=GIFTHIVE-20', 'B0BHCPFPM8', ARRAY['for-him','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Telescoping stainless steel scratchers that reach anywhere an itch dares to hide.', 'Three of them so I keep one in every room, oddly the best five bucks I spent.'),
  ('MINKINH Manicure Set 26 Pieces', 12.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0F1CW3CCK?tag=GIFTHIVE-20', 'B0F1CW3CCK', ARRAY['for-him','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Pro-grade 26-piece nail and grooming kit in a zippered case for travel or desk.', 'The tools feel weighty and sharp, way better than drugstore clippers.'),
  ('TUKUOS Telescoping Back Scratcher', 12.96, 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B09232JHMY?tag=GIFTHIVE-20', 'B09232JHMY', ARRAY['for-him','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Extendable stainless scratcher with a comfortable grip handle for hard-to-reach spots.', 'Extends long enough to actually reach my whole back, a small relief.'),
  ('MINKINH Manicure Set Brown', 9.98, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B09N1B6LL3?tag=GIFTHIVE-20', 'B09N1B6LL3', ARRAY['for-him','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Slim brown leather-look case with a curated set of sharp grooming essentials.', 'Tucks into my dopp kit perfectly and the clippers are surprisingly sharp.'),
  ('TempPro Digital Meat Thermometer', 8.98, 'https://images.unsplash.com/photo-1587829741381-af9386f64498?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07Y51PCW7?tag=GIFTHIVE-20', 'B07Y51PCW7', ARRAY['for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Foldable instant-read probe that delivers an accurate temp in seconds.', 'Reads fast and the fold-out probe means no stabbed fingers in the drawer.'),
  ('O''Keeffe''s Working Hands Hand Cream', 8.89, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B00121UVU0?tag=GIFTHIVE-20', 'B00121UVU0', ARRAY['for-him','for-parents']::text[], ARRAY['christmas','thanks']::text[], 'cheap', 'Concentrated glycerin balm that fixes cracked, working hands overnight.', 'Cleared up the cracks on my knuckles in two nights, nothing else worked.'),
  ('Bellavita Men''s Perfume Gift Set', 26.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B09231NL5H?tag=GIFTHIVE-20', 'B09231NL5H', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Four-piece fragrance sampler so he can test designer-inspired scents before committing.', 'Surprised how long the scent lasted, got compliments at the office all week.'),
  ('Bodystance Backpod Back Posture', 68.88, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B01LYNZBV3?tag=GIFTHIVE-20', 'B01LYNZBV3', ARRAY['for-him','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Contoured device that loosens a stiff upper back and reverses slouch posture.', 'Five minutes a night and my back stopped cracking every time I stood up.'),
  ('DUDE Wipes Flushable 48 Count', 4.58, 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B00L1GHHV2?tag=GIFTHIVE-20', 'B00L1GHHV2', ARRAY['for-him']::text[], ARRAY['thanks']::text[], 'cheap', 'Soothing flushable wipes with aloe that actually break down in the pipes.', 'Honest upgrade over dry paper, and they have not clogged my toilet once.'),
  ('Boxbollen Boxing Reflex Ball', 29.99, 'https://images.unsplash.com/photo-1558877385-81a1c7e67d72?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0BZ8MB4KM?tag=GIFTHIVE-20', 'B0BZ8MB4KM', ARRAY['for-him','for-kids']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Headband-mounted reflex ball that sharpens hand-eye coordination and burns off energy.', 'Embarrassingly addictive, I keep sneaking in rounds between meetings.'),
  ('Airmoto Tire Inflator Portable', 69.99, 'https://images.unsplash.com/photo-1587829741381-af9386f64498?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B094DMH7ZM?tag=GIFTHIVE-20', 'B094DMH7ZM', ARRAY['for-him']::text[], ARRAY['birthday','christmas']::text[], 'high', 'Cordless digital air compressor that tops off tires in under two minutes.', 'Saved me from a gas station line at midnight, totally worth every dollar.'),
  ('Burt''s Bees Classics Gift Set', 25.00, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B00VK5SG46?tag=GIFTHIVE-20', 'B00VK5SG46', ARRAY['for-her','for-parents']::text[], ARRAY['christmas','thanks']::text[], 'mid', 'Five travel-size Burt''s Bees staples in a tin, ready to drop in a stocking.', 'Smells like the holiday aisle and every single item got used up.'),
  -- === CANDLES & HOME FRAGRANCE ===
  ('GODONLIF Candle Warmer Lamp', 21.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CTJGJL2T?tag=GIFTHIVE-20', 'B0CTJGJL2T', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Top-down warming lamp that releases scent without an open flame or soot.', 'No more black soot on my ceiling and the throw is stronger than lighting the wick.'),
  ('Candle Warmer Lamp with Timer', 9.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0DZFGTCLR?tag=GIFTHIVE-20', 'B0DZFGTCLR', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Compact bulb warmer with an auto-off timer for flame-free fragrance.', 'The timer means I never forget to turn it off before leaving the house.'),
  ('Marycele Candle Warmer Lamp', 20.00, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0BWJRJYS7?tag=GIFTHIVE-20', 'B0BWJRJYS7', ARRAY['for-her']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Vintage-style lamp that melts candles evenly for a clean, long-lasting scent.', 'Looks like a little lamp on my shelf and melts wax way faster than I expected.'),
  ('AOOVOO Coconut Vanilla Candle 9oz', 13.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CP7QMZF9?tag=GIFTHIVE-20', 'B0CP7QMZF9', ARRAY['for-her']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Soy-blend candle with creamy coconut and warm vanilla notes in a glass jar.', 'Smells like a beach vacation and the wax burns down evenly with no tunneling.'),
  ('Lavender Spa Gift Basket Set', 19.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CFXFBG4L?tag=GIFTHIVE-20', 'B0CFXFBG4L', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Curated lavender spa bundle with candle, bath bombs, and body lotion.', 'Came packaged like a real gift, my mom did not want to open it at first.'),
  ('Chesapeake Bay Serenity+Calm Candle', 7.50, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B07GH691SQ?tag=GIFTHIVE-20', 'B07GH691SQ', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Soft lavender sandalwood candle in a frosted jar for a calming evening.', 'The throw is gentle, not overpowering, perfect for winding down.'),
  ('Hummingbird Rotating Scented Candle', 24.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0C4CX76KJ?tag=GIFTHIVE-20', 'B0C4CX76KJ', ARRAY['for-her']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Decorative candle holder with a spinning hummingbird lit by the candle''s glow.', 'The little hummingbird spins from the heat, my niece was mesmerized.'),
  ('Craftique You''re Amazing Candle', 13.97, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0DYMW78WD?tag=GIFTHIVE-20', 'B0DYMW78WD', ARRAY['for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Encouraging label candle with a fresh scent, ready to gift as a pick-me-up.', 'The message on the jar made my friend tear up before she even lit it.'),
  ('Chesapeake Bay Balance+Harmony', 17.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B01N0RSCBI?tag=GIFTHIVE-20', 'B01N0RSCBI', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Cedar and orange blossom candle in a sea-glass-inspired frosted jar.', 'The jar alone is beautiful, I am reusing it as a small vase after.'),
  ('BFFLOVE Cherry Blossom Spa Set', 9.99, 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B085XT846T?tag=GIFTHIVE-20', 'B085XT846T', ARRAY['for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Budget-friendly cherry blossom bath and body set in a giftable box.', 'Bought one for my bestie and she texted me a spa selfie the same night.'),
  ('6 Pack Candles Aromatherapy Set', 24.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B08XZ3HWF3?tag=GIFTHIVE-20', 'B08XZ3HWF3', ARRAY['for-her','for-parents']::text[], ARRAY['christmas','birthday']::text[], 'mid', 'Six travel tin candles in different calming scents for a season of cozy evenings.', 'Each tin lasts longer than I thought and the scents actually differ.'),
  ('6 Pack Scented Candles Gift Set', 32.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CHYWN5W6?tag=GIFTHIVE-20', 'B0CHYWN5W6', ARRAY['for-her','for-parents']::text[], ARRAY['christmas','birthday']::text[], 'mid', 'Luxury tin candle set with floral and woody fragrance notes for gifting.', 'The packaging is genuinely gift-ready, I did not even wrap it.'),
  ('Lihome Happy Birthday Candle', 12.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0CJR8949L?tag=GIFTHIVE-20', 'B0CJR8949L', ARRAY['for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Festive label candle that doubles as a birthday cake topper.', 'Smelled like vanilla frosting and my friend kept it on her desk after.'),
  ('Yankee Candle Mid Summer''s Night 22oz', 14.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0F3DQSZKT?tag=GIFTHIVE-20', 'B0F3DQSZKT', ARRAY['for-him','for-her']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Classic large jar candle with a masculine musky, sage, and citrus blend.', 'That distinctive Yankee throw filled my whole living room within minutes.'),
  ('Yankee Candle Pink Sands 22oz', 14.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0F3DQK6YY?tag=GIFTHIVE-20', 'B0F3DQK6YY', ARRAY['for-her']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Coconut, citrus, and floral blend in a signature large jar candle.', 'Smells exactly like a beach holiday, my favorite candle of the year.'),
  ('Yankee Candle Lemon Lavender 22oz', 14.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0F3F5FHWT?tag=GIFTHIVE-20', 'B0F3F5FHWT', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Soothing lemon and herbaceous lavender blend in a 22-ounce jar.', 'Fresh but calm, my mom keeps asking where I bought it.'),
  ('Yankee Candle Sage & Citrus 22oz', 14.99, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B0F3DQPLSP?tag=GIFTHIVE-20', 'B0F3DQPLSP', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Earthy sage balanced with bright citrus in a long-burning jar candle.', 'Smells like an herb garden after rain, surprisingly sophisticated.'),
  ('Bath & Body Works Mahogany Teakwood 3-Wick', 21.49, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B01M7TTA2S?tag=GIFTHIVE-20', 'B01M7TTA2S', ARRAY['for-him','for-her']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Masculine wood and teak three-wick candle that fills a room fast.', 'Smells like a fancy cologne and the three wicks melt the wax evenly.'),
  ('Capri Blue Volcano Scented Candle 19oz', 35.00, 'https://images.unsplash.com/photo-1602874801006-7c0f4a3e9e73?w=800&h=600&fit=crop&q=80', 'https://www.amazon.com/dp/B000YBFJQU?tag=GIFTHIVE-20', 'B000YBFJQU', ARRAY['for-her','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Cult-favorite tropical citrus and sugar candle in a signature mercury jar.', 'Worth the hype, the jar is gorgeous and the scent is unmistakable.'),
